"use strict";
// Source data is generated by Python at build time; drawing and interactions run in JavaScript.
(() => {
 const research=window.FRIENDS_V05.research;
 let metric='both';
 const labels={doing:'Likelihood of doing when lonely',loneliness:'Likelihood of feeling lonely'};
 function draw(){
  const keys=metric==='both'?['doing','loneliness']:[metric];
  $('#study1-bars').innerHTML=research.activities.map((row,i)=>`<div class="study-row"><strong>${esc(row.activity)}</strong><div class="study-series">${keys.map(key=>`<button class="study-bar ${key}" data-study-row="${i}" data-study-key="${key}" aria-label="${esc(row.activity)}: ${labels[key]}, ${row[key].toFixed(2)} on a 1 to 7 scale"><span class="bar-track"><i style="width:${row.display_percent[key]}%"></i></span><b>${row[key].toFixed(2)}</b></button>`).join('')}</div></div>`).join('');
 }
 $('#study1-table').insertAdjacentHTML('beforeend',`<p>${esc(research.note)}</p><table><caption>Published descriptive means · Paper A, Study 1</caption><thead><tr><th scope="col">Activity</th><th scope="col">Doing when lonely</th><th scope="col">Feeling lonely</th></tr></thead><tbody>${research.activities.map(row=>`<tr><th scope="row">${esc(row.activity)}</th><td>${row.doing.toFixed(2)}</td><td>${row.loneliness.toFixed(2)}</td></tr>`).join('')}</tbody></table>`);
 $$('[data-study-metric]').forEach(button=>button.onclick=()=>{metric=button.dataset.studyMetric;$$('[data-study-metric]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));draw();$('#study1-tooltip').textContent='Published descriptive means. Response scales 1–7; display axis starts at zero.';});
 function tooltip(event){const button=event.target.closest?.('[data-study-row]');if(!button)return;const row=research.activities[Number(button.dataset.studyRow)],key=button.dataset.studyKey;$('#study1-tooltip').textContent=`${row.activity} · ${labels[key]}: ${row[key].toFixed(2)} / 7. ${key==='doing'?'Higher means more likely to choose.':'Reverse-scored; lower means less likely to feel lonely.'}`;}
 ['focusin','pointerover','click'].forEach(name=>$('#study1-bars').addEventListener(name,tooltip));draw();

 // Reveal without an event-catching overlay: the bottom zone never blocks slide content.
 const overlay=$('#navigation-overlay'),toggle=$('#nav-toggle');
 let timer=0,manual=false,inZone=false;
 const focused=()=>overlay.contains(document.activeElement);
 function show(){clearTimeout(timer);timer=0;document.body.classList.add('nav-open');toggle.setAttribute('aria-expanded','true');}
 function hide(){if(focused()||manual)return;document.body.classList.remove('nav-open');toggle.setAttribute('aria-expanded','false');}
 function delayHide(){if(timer||focused()||manual)return;timer=setTimeout(()=>{timer=0;hide();},1300);}
 document.addEventListener('pointermove',event=>{if(event.pointerType==='touch')return;const next=event.clientY>=innerHeight-88;if(next){show();}else if(inZone){delayHide();}inZone=next;});
 overlay.addEventListener('pointerenter',()=>show());overlay.addEventListener('pointerleave',()=>{inZone=false;delayHide();});
 overlay.addEventListener('focusin',()=>show());overlay.addEventListener('focusout',()=>queueMicrotask(()=>{if(!focused())delayHide();}));
 toggle.onclick=()=>{manual=!manual;if(manual)show();else hide();};
 document.addEventListener('pointerdown',event=>{if(!overlay.contains(event.target)&&!toggle.contains(event.target)){manual=false;delayHide();}});
 document.addEventListener('keydown',event=>{if(event.key==='Escape'&&!document.querySelector('dialog[open]')){manual=false;if(focused())presentation.focus({preventScroll:true});hide();}});
 window.FriendsNavigation={show,hide:()=>{manual=false;hide();},get visible(){return document.body.classList.contains('nav-open');}};
})();
